"""Private local viewer, isolated from the production Site."""
from pathlib import Path
import json,hashlib
O=Path(__file__).resolve().parent;B=O.parent.parent;S=B.parents[3].parent/'recipe-atlas'
def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
(O/'vendor').mkdir(exist_ok=True)
copied=[]
for name in ['3Dmol-min.js','3Dmol-min.js.LICENSE.txt']:
 p=S/'dist/vendor'/name;dest=O/'vendor'/name;dest.write_bytes(p.read_bytes());copied.append({'source':str(p),'target':str(dest),'sha256':sha(p)})
(O/'viewer-runtime-inputs.json').write_text(json.dumps(copied,indent=2)+'\n',encoding='utf-8')
data={'registry':read(O/'registry-additions.json'),'slots':read(O/'source-slot-mapping.json')['slots'],'bindings':read(O/'molecule-bindings-proposal.json'),'stocks':read(O/'stock-component-selectors.json')['stocks'],'models':{p.name:read(p) for p in (O/'models').glob('*.json')}}
payload=json.dumps(data,ensure_ascii=False).replace('</','<\\/')
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nagasaki · private component viewer</title>
<style>body{font:17px/1.5 system-ui;color:#223f50;background:#f1f5f7;margin:25px auto;max-width:1200px;padding:0 15px}h1{font-size:31px}h2{font-size:21px}.toolbar,article,section{background:white;border:1px solid #cedce3;border-radius:15px;padding:20px;margin-bottom:20px}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(350px,1fr));gap:20px}article img{width:100%;cursor:pointer}button,select,input{font:inherit;padding:9px;border:1px solid #a4bbc8;border-radius:7px;background:white;max-width:100%}button{cursor:pointer;color:#214c65}p{margin:9px 0}.muted{color:#607582;font-size:14px}dialog{width:min(1000px,92vw);max-height:90vh;border:1px solid #b5c8d3;border-radius:17px;padding:22px}dialog::backdrop{background:#16364c80}#model{height:430px;position:relative;background:#f8fafc;overflow:auto}#model img{width:100%;height:100%;object-fit:contain;transform-origin:center}#buttons{display:flex;gap:10px;margin:14px 0;flex-wrap:wrap}.stock-row{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.stock-note{background:#f0f7fa;padding:15px;border-radius:9px}.group{display:inline-block;border-left:5px solid;margin:5px;padding:0 7px}pre{white-space:pre-wrap}article[hidden]{display:none}</style>
<h1>Nagasaki 2004 · precursor and component viewers</h1><p>Private author review: 42 identities, 61 source slots. Independent scientific and binding review is pending.</p>
<section id="stocks"><h2>Stock components</h2><p class="muted">Select a solute or solvent separately. These controls do not represent a combined solution structure.</p></section>
<section><h2>Source-slot viewer</h2><div class="stock-row"><select id="record"></select><select id="slot"></select><button id="openslot">Inspect selected source component</button></div><p id="slotnote" class="muted"></p></section>
<div class="toolbar"><label>Filter references <input id="search" type="search" placeholder="Name or source scope"></label></div><main id="cards"></main>
<dialog id="dialog"><button id="close" style="float:right">Close ×</button><h2 id="title"></h2><p id="formula"></p><div id="model"></div><div id="buttons"></div><div id="groups"></div><p id="modelcaption"></p><p id="bindingcaption"></p><div id="refs"></div></dialog>
<script src="vendor/3Dmol-min.js"></script><script id="data" type="application/json">PAYLOAD</script><script>
const data=JSON.parse(document.querySelector('#data').textContent),entries=new Map(data.registry.entries.map(e=>[e.id,e])),q=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
let viewer=null,active=null,mode=null,scale=1;
const palette=['#d49737','#62a8b6','#aa84bf','#cc8395'];
function modelFor(e,dim){return data.models[(e[dim===3?'model3dPath':'model2dPath']||'').split('/').pop()];}
function render(e,dim){mode=dim;scale=1;viewer?.clear();viewer=null;q('#model').replaceChildren();q('#groups').replaceChildren();let m=modelFor(e,dim);
 if(dim===3&&m&&window.$3Dmol){viewer=$3Dmol.createViewer(q('#model'),{backgroundColor:'#f8fafc'});const aa=m.atoms.map((a,i)=>({index:i,serial:i,elem:a.element??a.elem,x:a.x,y:a.y,z:a.z,bonds:[],bondOrder:[]}));for(const b of m.bonds){aa[b.a].bonds.push(b.b);aa[b.a].bondOrder.push(b.order);aa[b.b].bonds.push(b.a);aa[b.b].bondOrder.push(b.order)}viewer.addModel().addAtoms(aa);
  const style=on=>{viewer.setStyle({},{stick:{radius:.12},sphere:{scale:.25}});if(on)(m.functionalGroups||[]).forEach((g,i)=>viewer.setStyle({index:g.atomIndices},{stick:{radius:.16,color:palette[i%4]},sphere:{scale:.28,color:palette[i%4]}}));viewer.render()};style(true);viewer.zoomTo();viewer.zoom(.85);viewer.render();if(m.functionalGroups?.length){const label=document.createElement('label');label.innerHTML='<input type="checkbox" checked> Highlight functional groups';label.querySelector('input').onchange=ev=>style(ev.target.checked);q('#groups').append(label);m.functionalGroups.forEach((g,i)=>{const s=document.createElement('span');s.className='group';s.style.borderColor=palette[i%4];s.textContent=g.label;q('#groups').append(s)})}
 }else{const img=new Image();img.src=e.svgPath;img.alt=e.name;q('#model').append(img);}
 q('#modelcaption').textContent=dim===3&&m?m.caption:e.caption;q('#buttons').replaceChildren();for(const [label,f] of [['−',1/1.2],['Reset',0],['+',1.2]]){const b=document.createElement('button');b.textContent=label;b.onclick=()=>{if(viewer){f?viewer.zoom(f):viewer.zoomTo();viewer.render()}else{scale=f?Math.max(.5,Math.min(4,scale*f)):1;q('#model img').style.transform=`scale(${scale})`}};q('#buttons').append(b)}if(e.model3dPath){const toggle=document.createElement('button');toggle.textContent=dim===3?'Show 2D connectivity':'Show reference 3D';toggle.onclick=()=>render(e,dim===3?2:3);q('#buttons').append(toggle)}
}
function openEntry(e,note){active=e;q('#title').textContent=note?.source_name||e.name;q('#formula').textContent=e.formula?`Reference formula: ${e.formula}`:'Symbolic source identity; exact formula not assigned';q('#bindingcaption').textContent=note?.display_scope||e.limitations.join(' ');q('#refs').replaceChildren();e.sourceUrls.forEach(url=>{const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.textContent='Chemical/source reference ↗';q('#refs').append(a,document.createElement('br'))});q('#dialog').showModal();render(e,e.model3dPath?3:2)}
q('#close').onclick=()=>q('#dialog').close();q('#dialog').onclose=()=>{viewer?.clear();viewer=null};
for(const e of data.registry.entries){const a=document.createElement('article');a.innerHTML=`<h2>${esc(e.name)}</h2><img src="${e.svgPath}" alt="${esc(e.name)}" loading="lazy"><p>${esc(e.caption)}</p><p class="muted">${esc(e.limitations.join(' '))}</p>`;const b=document.createElement('button');b.textContent=e.model3dPath?'Explore reference molecule':'Inspect symbolic / 2D reference';b.onclick=()=>openEntry(e);a.querySelector('img').onclick=b.onclick;a.append(b);q('#cards').append(a)}
q('#search').oninput=ev=>q('#cards').querySelectorAll('article').forEach(a=>a.hidden=!a.textContent.toLowerCase().includes(ev.target.value.toLowerCase()));
for(const rid of Object.keys(data.bindings.recordBindings)){if(!Object.keys(data.bindings.recordBindings[rid]).length)continue;const o=new Option(rid,rid);q('#record').append(o)}
function slots(){q('#slot').replaceChildren();const rid=q('#record').value;for(const [mid,id] of Object.entries(data.bindings.recordBindings[rid]))q('#slot').append(new Option(data.bindings.bindingNotes[rid][mid].source_name,mid));note()}
function note(){const n=data.bindings.bindingNotes[q('#record').value][q('#slot').value];q('#slotnote').textContent=n.display_scope}
q('#record').onchange=slots;q('#slot').onchange=note;q('#openslot').onclick=()=>{const rid=q('#record').value,mid=q('#slot').value;openEntry(entries.get(data.bindings.recordBindings[rid][mid]),data.bindings.bindingNotes[rid][mid])};slots();
function quantity(q){if(q.status==='not_reported')return `Not reported (${q.unit||'unit not stated'})`;let v=q.value??(q.minimum!=null?`≥${q.minimum}`:q.maximum!=null?`≤${q.maximum}`:'Not reported');return `${q.approximate?'approximately ':''}${v} ${q.unit||''}${q.qualifier?' — '+q.qualifier:''}`}
for(const stock of data.stocks){const wrap=document.createElement('section'),select=document.createElement('select');wrap.innerHTML=`<h2>${esc(stock.name)}</h2>`;stock.components.forEach(c=>select.append(new Option(entries.get(c.registry_id).name,c.registry_id)));const button=document.createElement('button');button.textContent='Inspect component';button.onclick=()=>{const c=stock.components.find(c=>c.registry_id===select.value);openEntry(entries.get(select.value),data.bindings.bindingNotes[stock.record_id][c.material_id])};const row=document.createElement('div');row.className='stock-row';row.append(select,button);wrap.append(row);const p=document.createElement('p');p.className='stock-note';const statements=[];for(const c of stock.components)for(const [key,v]of Object.entries(c.canonical_component.quantities||{}))statements.push(entries.get(c.registry_id).name+': '+quantity(v));for(const [key,v]of Object.entries(stock.concentrations||{}))statements.push(key.replaceAll('_',' ')+': '+quantity(v));p.textContent=statements.join(' · ');wrap.append(p);const n=document.createElement('p');n.className='muted';n.textContent=stock.scope;wrap.append(n);q('#stocks').append(wrap)}
</script></html>'''
(O/'viewer.html').write_text(html.replace('PAYLOAD',payload),encoding='utf-8')
print('Wrote private viewer.html with 42 entries, 61 exact slot options and 2 component selectors.')
